   140  static char *
   141  strsep_char(char *strp, char delim)
   142  {
   143      char *ptr;
   144
   145      if (UNLIKELY(!strp))
   146          return NULL;
   147
   148      ptr = strchr(strp, delim);
   149      if (UNLIKELY(!ptr))
   150          return NULL;
   151
   152      *ptr = '\0';
   153      return ptr + 1;
   154  }
